from abc import ABC, abstractmethod
from typing import Dict, Any, Union, Optional
import json

class BaseTool(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        """Tool name that matches the regex ^[a-zA-Z0-9_-]{1,64}$"""
        pass

    @property
    @abstractmethod
    def description(self) -> str:
        """Detailed description of what the tool does"""
        pass

    @property
    @abstractmethod
    def input_schema(self) -> Dict:
        """JSON Schema defining the expected parameters"""
        pass

    @abstractmethod
    def execute(self, **kwargs) -> Union[str, Dict, Any]:
        """Execute the tool with given parameters"""
        pass

    def format_result(self, result: Any) -> Dict[str, Any]:
        """
        Standardize tool output into a consistent format.
        Handles base64 stripping and large content placeholders.
        """
        def _clean_data(data: Any) -> Any:
            """Recursively clean data for display and serialization."""
            if isinstance(data, str):
                # Handle base64 data
                if ';base64,' in data or data.startswith('data:'):
                    if len(data) > 1000:
                        return "[base64 data omitted]"
                # Handle long strings
                elif len(data) > 10000:
                    return f"[large content omitted ({len(data)} chars)]"
                return data
            elif isinstance(data, dict):
                cleaned = {}
                for key, value in data.items():
                    # Handle image/data fields
                    if key in ['data', 'image', 'source'] and isinstance(value, str):
                        if len(value) > 1000 and (';base64,' in value or value.startswith('data:')):
                            cleaned[key] = "[base64 data omitted]"
                        else:
                            cleaned[key] = _clean_data(value)
                    else:
                        cleaned[key] = _clean_data(value)
                return cleaned
            elif isinstance(data, list):
                return [_clean_data(item) for item in data]
            elif isinstance(data, (int, float, bool)):
                return data
            elif data is None:
                return None
            else:
                return str(data)

        # Ensure result is serializable
        try:
            if isinstance(result, (dict, list)):
                cleaned_result = _clean_data(result)
            else:
                cleaned_result = _clean_data(str(result) if not isinstance(result, str) else result)

            return {
                "success": True,
                "content": cleaned_result
            }
        except Exception as e:
            return {
                "success": False,
                "error": str(e),
                "content": None
            }
